use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclstruct! {
# [doc = " A fixed-size bitset type with a partially dense, partially sparse"] # [doc = " representation. The bitset is broken into chunks, and chunks that are all"] # [doc = " zeros or all ones are represented and handled very efficiently."] # [doc = ""] # [doc = " This type is especially efficient for sets that typically have a large"] # [doc = " `domain_size` with significant stretches of all zeros or all ones, and also"] # [doc = " some stretches with lots of 0s and 1s mixed in a way that causes trouble"] # [doc = " for `IntervalSet`."] # [doc = ""] # [doc = " Best used via `MixedBitSet`, rather than directly, because `MixedBitSet`"] # [doc = " has better performance for small bitsets."] # [doc = ""] # [doc = " `T` is an index type, typically a newtyped `usize` wrapper, but it can also"] # [doc = " just be `usize`."] # [doc = ""] # [doc = " All operations that involve an element will panic if the element is equal"] # [doc = " to or greater than the domain size. All operations that involve two bitsets"] # [doc = " will panic if the bitsets have differing domain sizes."] # [derive (PartialEq , Eq)] pub struct ChunkedBitSet < T > { domain_size : usize , # [doc = " The chunks. Each one contains exactly CHUNK_BITS values, except the"] # [doc = " last one which contains 1..=CHUNK_BITS values."] chunks : Box < [Chunk] > , marker : PhantomData < T > , }
}